//! Mixture search: NNLS parity with `scipy.optimize.nnls` (background columns included) and the forward selection
//! against its reference, from `tests/golden/miscele/*.json` (regenerated by hand with `tools/miscele_riferimento.py`).
use ftir_core::miscele::dati::Thresholds;
use ftir_core::miscele::nnls;
use ftir_core::miscele::seleziona::{forward, Problem};
use ftir_core::passi::json::{parse, Value};

fn golden(name: &str) -> Value {
    let path = format!(
        "{}/tests/golden/miscele/{name}.json",
        env!("CARGO_MANIFEST_DIR")
    );
    parse(&std::fs::read_to_string(path).expect("golden file")).expect("golden json")
}

fn nums(v: &Value) -> Vec<f64> {
    v.as_arr()
        .expect("array")
        .iter()
        .map(|n| n.as_f64().expect("number"))
        .collect()
}

fn rows(v: &Value) -> Vec<Vec<f64>> {
    v.as_arr().expect("rows").iter().map(nums).collect()
}

fn field<'a>(v: &'a Value, key: &str) -> &'a Value {
    v.get(key).unwrap_or_else(|| panic!("missing {key}"))
}

#[test]
fn nnls_agrees_with_scipy_to_1e_9() {
    let g = golden("nnls");
    for (n, case) in field(&g, "cases")
        .as_arr()
        .expect("cases")
        .iter()
        .enumerate()
    {
        let columns = rows(field(case, "columns"));
        let refs: Vec<&[f64]> = columns.iter().map(Vec::as_slice).collect();
        let b = nums(field(case, "b"));
        let want = nums(field(case, "x"));
        let rss = field(case, "rss").as_f64().expect("rss");
        let fit = nnls::solve(&refs, &b);
        let scale = want.iter().fold(1e-300f64, |m, v| m.max(v.abs()));
        for (j, (got, w)) in fit.x.iter().zip(&want).enumerate() {
            assert!(
                (got - w).abs() <= 1e-9 * scale,
                "case {n} x[{j}]: got {got} want {w}"
            );
        }
        assert!(
            (fit.rss - rss).abs() <= 1e-9 * rss.max(1e-12),
            "case {n} rss {} {rss}",
            fit.rss
        );
    }
}

#[test]
fn forward_selection_picks_what_the_reference_picks() {
    let th = Thresholds::embedded().expect("thresholds");
    let g = golden("selezione");
    for case in field(&g, "cases").as_arr().expect("cases") {
        let name = field(case, "name").as_str().expect("name");
        let y = nums(field(case, "y"));
        let columns = rows(field(case, "columns"));
        let cuts: Vec<bool> = field(case, "is_cut")
            .as_arr()
            .expect("flags")
            .iter()
            .map(|v| matches!(v, Value::Bool(true)))
            .collect();
        let p = Problem::new(y, columns.clone(), cuts, th.background_order);
        let all: Vec<usize> = (0..columns.len()).collect();
        let sel = forward(&p, &all, &th).expect("selection");
        let picks: Vec<usize> = sel.picks.iter().map(|p| p.candidate).collect();
        let want: Vec<usize> = nums(field(case, "picks"))
            .iter()
            .map(|v| *v as usize)
            .collect();
        assert_eq!(picks, want, "{name}: picks");
        for (got, w) in sel.weights.iter().zip(nums(field(case, "weights"))) {
            assert!(
                (got - w).abs() <= 1e-9 * w.abs().max(1.0),
                "{name}: weight {got} {w}"
            );
        }
        let total = field(case, "total").as_f64().expect("total");
        assert!((sel.total - total).abs() <= 1e-9 * total, "{name}: total");
    }
}
